package main

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"testing"
)

// Vectors are generated by LocalIndexInterop.java with the production Android
// codec, not by Go's sealer. This detects AAD/encoding/protocol incompatibility.
func TestAndroidPublishedIndexCrossDeviceSync(t *testing.T) {
	source := testCloudRuntime(t, filepath.Join(t.TempDir(), "hub"), "")
	target := testCloudRuntime(t, filepath.Join(t.TempDir(), "receiver"), "")
	if err := os.WriteFile(filepath.Join(target.disk.dir, "recovery.key"), bytes.Repeat([]byte{0x11}, 32), 0600); err != nil {
		t.Fatal(err)
	}
	client, err := newCloudClient(target)
	if err != nil {
		t.Fatal(err)
	}
	token := "android-interop-token-012345678901"
	peer := serveCloudTestNode(t, source, token)
	file, err := os.Open("testdata/android-index-records.jsonl")
	if err != nil {
		t.Fatal(err)
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	phase := 0
	for scanner.Scan() {
		raw := append([]byte{}, scanner.Bytes()...)
		var record cloudRecord
		if err = json.Unmarshal(raw, &record); err != nil {
			t.Fatal(err)
		}
		manifest, err := client.openManifest(record)
		if err != nil {
			t.Fatalf("Android phase %d cannot decrypt: %v", phase, err)
		}
		if manifest.LocalIndex == nil || manifest.LocalIndex.Name != "照片.jpg" {
			t.Fatalf("invalid Android manifest: %+v", manifest)
		}
		// Replaying a pending upload is idempotent, then another node fetches it.
		for retry := 0; retry < 2; retry++ {
			request, err := http.NewRequest(http.MethodPut, peer.URL+"/cloud/catalog/"+cloudHash(raw), bytes.NewReader(raw))
			if err != nil {
				t.Fatal(err)
			}
			request.Header.Set("Authorization", "Bearer "+token)
			response, err := http.DefaultClient.Do(request)
			if err != nil {
				t.Fatal(err)
			}
			response.Body.Close()
			if response.StatusCode != http.StatusNoContent {
				t.Fatalf("Android PUT failed: %d", response.StatusCode)
			}
		}
		if err = target.syncCatalog(context.Background(), peer.URL, token); err != nil {
			t.Fatal(err)
		}
		files, err := client.mergeCatalogSearch(nil, true)
		if err != nil {
			t.Fatal(err)
		}
		if phase == 3 {
			if len(files) != 0 {
				t.Fatalf("removed phone file remains searchable: %+v", files)
			}
		} else {
			if len(files) != 1 || !files[0].LocalOnly || len(files[0].Locations) != 1 {
				t.Fatalf("phone index duplicated or missing: %+v", files)
			}
			if files[0].Locations[0].ResourceRef != "Y29udGVudDovL3Rlc3QvcGhvdG8uanBn" || files[0].Locations[0].Path != "" {
				t.Fatalf("phone source cannot be resolved without exposing its SAF URI: %+v", files[0].Locations[0])
			}
			switch phase {
			case 0:
				if files[0].FolderName != "旅行照片" || len(files[0].Tags) != 1 || files[0].Tags[0] != "旅行" {
					t.Fatal(files[0])
				}
			case 1:
				if files[0].FolderName != "家庭照片" || len(files[0].Tags) != 2 || files[0].Tags[0] != "家庭" {
					t.Fatal(files[0])
				}
			case 2:
				if files[0].FolderID != "" || files[0].FolderName != "" || len(files[0].Tags) != 0 {
					t.Fatalf("removed classifications resurrected: %+v", files[0])
				}
			}
		}
		record.AuthorID = "tampered-author"
		if _, err = client.openManifest(record); err == nil {
			t.Fatal("unauthenticated Android metadata accepted")
		}
		phase++
	}
	if err = scanner.Err(); err != nil {
		t.Fatal(err)
	}
	if phase != 4 {
		t.Fatalf("expected four Android snapshots, got %d", phase)
	}
}

func TestMergeIndexedLocationsKeepsDistinctOpaqueReferences(t *testing.T) {
	locations := mergeIndexedLocations(
		[]indexedLocation{{NodeID: "phone", StorageID: "root", ResourceRef: "first"}},
		[]indexedLocation{{NodeID: "phone", StorageID: "root", ResourceRef: "second"}, {NodeID: "phone", StorageID: "root", ResourceRef: "first"}},
	)
	if len(locations) != 2 {
		t.Fatalf("opaque source references were collapsed or duplicated: %+v", locations)
	}
}
